import type { GameDifficultyTier } from '../../_shared/types';

/**
 * 9 x 9 block mazes. '#' is wall, '.' is floor. The player starts in the
 * centre (row 4, column 4); the four corner cells are the answer chambers.
 *
 * Every layout was generated by search and is unchanged by a quarter turn
 * around the centre, so the four chambers are exactly the same walking
 * distance from the start. Corridors are one cell wide (no open 2 x 2
 * blocks). Shortest path to a chamber: BEGINNER 8 steps, INTERMEDIATE 10,
 * ADVANCED 12. A mirrored copy of any layout keeps all of these properties.
 *
 * utils/maze.ts re-checks all of this in `checkLayout`.
 */
